// SIL Chat — monta o prompt que transforma a pergunta em SQL (DuckDB)
// Fluxo exclusivo da JA: a empresa é fixa aqui, nunca vem do payload
const COMPANY_ID = '8b4798b9-0386-4f04-95b4-913d2d868322';

const body = $input.first().json.body || {};
const pergunta = String(body.chatInput || body.message || '').trim();
// Histórico curto: cada token conta no limite por minuto da IA
const historico = Array.isArray(body.historico) ? body.historico.slice(-4) : [];
const conversa = historico
  .map((h) => (h.role === 'user' ? 'Usuário: ' : 'SIL: ') + String(h.content || '').slice(0, 300))
  .join('\n');

const agora = $now.setZone('America/Fortaleza');
const hoje = agora.toFormat('dd/MM/yyyy');
const mesAtual = Number(agora.toFormat('yyyyMM'));
const diasNoMes = agora.daysInMonth;
// A base é carregada às 06h com o faturamento até o dia anterior
const diasDecorridos = Math.max(agora.day - 1, 1);

const ESQUEMA = `
Tabela base_comercial — uma linha por VENDEDOR × MÊS × FILIAL
  mesanonum BIGINT (ex.: 202508), mes_ano VARCHAR (ex.: 'ago/25'), filial VARCHAR (ex.: '1 - JA DISTRIBUIDORA LTDA'),
  codusur BIGINT, nome VARCHAR (vendedor), supervisor VARCHAR,
  vl_faturados DOUBLE (faturamento R$), vl_venda DOUBLE, vl_lucro DOUBLE,
  margem_pct DOUBLE (fração), meta DOUBLE (R$, pode ser nula), pct_meta DOUBLE (fração),
  qtde_pedidos BIGINT, qtde_clientes BIGINT, ticket_medio DOUBLE, fat_anopassado DOUBLE, crescimento_pct DOUBLE (fração)

Tabela base_clientes — uma linha por CLIENTE × MÊS × FILIAL
  mesanonum, mes_ano, filial, codcli BIGINT, cliente VARCHAR, municcob VARCHAR (cidade), estcob VARCHAR (UF),
  ramo VARCHAR, vl_faturados, vl_lucro, margem_pct, qtde_pedidos, ticket_medio, fat_anopassado, crescimento_pct

Tabela base_produtos — uma linha por PRODUTO × MÊS × FILIAL
  mesanonum, mes_ano, filial, codprod BIGINT, descricao VARCHAR, marca VARCHAR, departamento VARCHAR, fornecedor VARCHAR,
  vl_faturados, vl_lucro, margem_pct, qtde_vendas BIGINT, soma_qtde DOUBLE (unidades), fat_anopassado, crescimento_pct
`;

const promptSql = `Você escreve UMA consulta SQL (dialeto DuckDB) sobre os dados comerciais da JA Distribuidora.

Hoje é ${hoje}. Mês atual: ${mesAtual}, em andamento (${diasDecorridos} de ${diasNoMes} dias corridos já faturados). Os dados cobrem os últimos 14 meses.
${ESQUEMA}
Regras:
- Filtre e ordene períodos por mesanonum; mes_ano só para exibir. "Mês passado" = maior mesanonum < ${mesAtual}. Sem período, use o mês atual.
- Cada linha é por filial: SOME (SUM) e agrupe pela entidade, a menos que peçam por filial.
- Margem = SUM(vl_lucro) / NULLIF(SUM(vl_faturados), 0). Ticket médio = SUM(vl_faturados) / NULLIF(SUM(qtde_pedidos), 0). % meta = SUM(vl_faturados) / NULLIF(SUM(meta), 0). Nunca faça média de colunas _pct.
- Percentuais sempre como FRAÇÃO (0.19 = 19%). Nunca multiplique por 100.
- Tendência (projeção de fechamento) do mês atual = SUM(vl_faturados) / ${diasDecorridos} * ${diasNoMes}. % de tendência = tendência / NULLIF(SUM(meta), 0). Nunca compare o mês atual parcial com um mês fechado sem projetar.
- Crescimento vs ano passado (só existe no mês atual) = SUM(vl_faturados) / NULLIF(SUM(fat_anopassado), 0) - 1.
- Faturamento total da empresa: base_comercial. Vendedor/supervisor/meta → base_comercial. Cliente/cidade/UF/ramo → base_clientes. Produto/marca/departamento/fornecedor → base_produtos.
- Textos em MAIÚSCULAS, às vezes sem acento: strip_accents(coluna) ILIKE strip_accents('%termo%').
- Rankings/listas: ORDER BY e LIMIT (máx. 50). Nunca devolva linhas brutas sem agregar. ROUND(x, 2) nos valores. Nomes de coluna curtos e claros, sem acento nem espaço (ex.: vendedor, faturamento, margem, tendencia).
- Continuação ("e em julho?", "gera um gráfico disso", "monte uma planilha"): refaça a consulta anterior com o ajuste pedido.
- Se não precisar de dados (saudação, ajuda), responda exatamente: SEM_CONSULTA

Conversa anterior:
${conversa || '(nenhuma)'}

Pergunta: ${pergunta}

Responda APENAS com o SQL (ou SEM_CONSULTA), sem explicação e sem markdown.`;

return [{ json: { pergunta, company_id: COMPANY_ID, hoje, mesAtual, diasNoMes, diasDecorridos, conversa, promptSql } }];

// Tira cercas de markdown; perguntas sem dados viram uma consulta inofensiva
const entrada = $input.first().json;
const texto = String(entrada.text || '').trim();
let sql = texto.replace(/^```(?:sql)?\s*/i, '').replace(/```\s*$/, '').trim();
if (entrada.error) {
  // A IA falhou ao gerar o SQL: segue sem consultar, e o "Responder"/"Montar Blocos" avisam o usuário
  sql = "select 'falha_ia' as aviso";
} else if (!sql || /^SEM_CONSULTA/i.test(sql)) {
  sql = "select 'sem_consulta' as aviso";
}
return [{ json: { sql } }];

// SIL Chat — prompt curto para a IA escrever só o resumo e dizer como formatar.
// A tabela e o gráfico são montados no "Montar Blocos" com os dados reais da consulta.
const p = $('Preparar Pergunta').first().json;
const sql = $('Extrair SQL').first().json.sql;
const r = $input.first().json;
const MAX_LINHAS_IA = 30;

let situacao;
if (sql.includes("'falha_ia'")) situacao = 'falha';
else if (sql.includes("'sem_consulta'")) situacao = 'conversa';
else if (!r.ok) situacao = 'erro';
else if (!r.rows || !r.rows.length) situacao = 'vazio';
else situacao = 'dados';

let promptResposta;
if (situacao === 'conversa') {
  promptResposta = `Você é a SIL, assistente comercial da JA Distribuidora. Você responde perguntas sobre faturamento, vendedores, supervisores, clientes, produtos, margem, metas e tendência do mês.

Conversa anterior:
${p.conversa || '(nenhuma)'}

Mensagem do usuário: ${p.pergunta}

Responda em português, em 1 a 3 frases, APENAS com JSON: {"resumo": "sua resposta"}`;
} else if (situacao === 'dados') {
  // Linhas como listas (sem repetir o nome da coluna em cada uma) para gastar menos tokens
  const linhas = r.rows.slice(0, MAX_LINHAS_IA).map((l) => r.colunas.map((c) => l[c]));
  const dados = JSON.stringify({ colunas: r.colunas, linhas, total_linhas: r.rows.length });

  promptResposta = `Você é a SIL, assistente comercial da JA Distribuidora. Hoje é ${p.hoje}; o mês atual (${p.mesAtual}) está em andamento.

Pergunta: ${p.pergunta}

SQL executado:
${sql}

Resultado (até ${MAX_LINHAS_IA} linhas):
${dados}

O sistema monta a tabela e o gráfico automaticamente com esses dados. NÃO repita a lista de valores.
Responda APENAS com JSON válido, sem markdown:
{
  "resumo": "1 a 3 frases respondendo a pergunta com os números principais (R$ 1.234.567,89; 19,0%)",
  "titulo": "título curto da tabela",
  "colunas": {"<coluna>": {"nome": "Nome amigável", "formato": "moeda|percentual|numero|texto"}},
  "grafico": null,
  "insight": null
}
- "percentual" = a coluna é fração (0.19 → 19,0%). Veja no SQL se houve multiplicação por 100; nesse caso use "numero".
- "grafico": só se o usuário pediu gráfico, ou para evolução mês a mês (line) ou ranking (horizontal-bar). Formato: {"tipo": "bar|horizontal-bar|line|pie", "titulo": "...", "rotulo": "<coluna das categorias>", "valores": ["<coluna numérica>"]}
- "insight": algo relevante (queda, destaque, concentração) ou null. Formato: {"severity": "info|success|warning|danger", "content": "..."}
- Use SOMENTE números do resultado. Nunca invente valores.`;
} else {
  // falha / erro / vazio: o "Montar Blocos" responde com uma mensagem fixa; a IA nem precisa pensar
  promptResposta = 'Responda apenas com: {"resumo": ""}';
}

return [{ json: { situacao, promptResposta } }];

// SIL Chat — monta a resposta final. Tabela e gráfico saem dos dados reais da consulta;
// da IA vem só o resumo, os nomes/formatos das colunas e o insight.
const { situacao } = $('Preparar Resposta').first().json;
const consulta = $('Consultar Base').first().json;
const entrada = $input.first().json;

const MENSAGENS = {
  falha: { type: 'insight', severity: 'warning', content: 'Não consegui responder agora. Tente novamente em alguns instantes.' },
  erro: { type: 'insight', severity: 'warning', content: 'Não consegui buscar essa informação. Tente reformular, indicando o período ou o nome do vendedor, cliente ou produto.' },
  vazio: { type: 'insight', severity: 'info', content: 'Não encontrei dados para esse filtro. Confira o período ou o nome pesquisado.' },
};

function responder(blocks) {
  const primeiro = blocks.find((b) => b.type === 'text' || b.type === 'insight');
  return [{ json: { blocks, message: primeiro ? primeiro.content : 'Resposta da SIL' } }];
}

// JSON da IA: tenta puro, depois só o trecho entre { e }, depois com reparos comuns
function lerJson(texto) {
  const inicio = texto.indexOf('{');
  const fim = texto.lastIndexOf('}');
  const trecho = inicio !== -1 && fim > inicio ? texto.slice(inicio, fim + 1) : texto;
  const reparado = trecho.replace(/[\x00-\x1f]+/g, ' ').replace(/,\s*([}\]])/g, '$1');
  for (const candidato of [texto, trecho, reparado]) {
    try {
      const j = JSON.parse(candidato);
      if (j && typeof j === 'object') return j;
    } catch (e) {}
  }
  return null;
}

const ia = entrada.error ? null : lerJson(String(entrada.text || '').trim());

if (MENSAGENS[situacao]) return responder([MENSAGENS[situacao]]);

if (situacao === 'conversa') {
  const resumo = (ia && ia.resumo) || 'Olá! Sou a SIL. Pergunte sobre faturamento, vendedores, clientes, produtos, margem ou metas.';
  return responder([{ type: 'text', content: resumo }]);
}

// ---- situacao === 'dados' ----
const colunas = consulta.colunas;
const linhas = consulta.rows.slice(0, 100);
const infoIa = (ia && ia.colunas) || {};

function formatoPadrao(coluna) {
  const nome = coluna.toLowerCase();
  const valores = linhas.map((l) => l[coluna]).filter((v) => v !== null && v !== undefined);
  if (!valores.length || !valores.every((v) => typeof v === 'number')) return 'texto';
  if (/(margem|pct|percent|cresc|particip|%)/.test(nome)) return 'percentual';
  if (/(fat|lucro|venda|meta|ticket|valor|receita|custo|tendencia|projec)/.test(nome)) return 'moeda';
  return 'numero';
}

const formato = {};
const nomeColuna = {};
for (const c of colunas) {
  const info = infoIa[c] || {};
  formato[c] = ['moeda', 'percentual', 'numero', 'texto'].includes(info.formato) ? info.formato : formatoPadrao(c);
  nomeColuna[c] = info.nome || c.replace(/_/g, ' ').replace(/^\w/, (l) => l.toUpperCase());
}

function dec(v, casas) {
  return v.toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
}

function fmt(v, f) {
  if (v === null || v === undefined || v === '') return '—';
  if (typeof v !== 'number') return String(v);
  if (f === 'moeda') return 'R$ ' + dec(v, 2);
  if (f === 'percentual') return dec(v * 100, 1) + '%';
  if (f === 'numero') return Number.isInteger(v) ? v.toLocaleString('pt-BR') : dec(v, 2);
  return String(v);
}

const blocks = [];
const resumo = ia && ia.resumo;
blocks.push({ type: 'text', content: resumo || 'Aqui estão os dados encontrados:' });

const g = ia && ia.grafico;
const tiposGrafico = ['bar', 'horizontal-bar', 'line', 'pie'];
if (g && tiposGrafico.includes(g.tipo) && colunas.includes(g.rotulo) && Array.isArray(g.valores)) {
  const valores = g.valores.filter((c) => colunas.includes(c) && formato[c] !== 'texto');
  if (valores.length) {
    const pontos = linhas.slice(0, 30);
    const emPercentual = formato[valores[0]] === 'percentual';
    blocks.push({
      type: 'chart',
      chartType: g.tipo,
      title: g.titulo || (ia && ia.titulo) || '',
      data: {
        labels: pontos.map((l) => String(l[g.rotulo])),
        datasets: valores.map((c) => ({
          // Percentuais vão em pontos percentuais (19,0) com "(%)" no nome da série
          label: nomeColuna[c] + (formato[c] === 'percentual' ? ' (%)' : ''),
          values: pontos.map((l) => {
            const v = Number(l[c]) || 0;
            return formato[c] === 'percentual' ? Math.round(v * 1000) / 10 : v;
          }),
        })),
      },
      config: { currency: formato[valores[0]] === 'moeda', percentage: false, showLegend: valores.length > 1 && !emPercentual },
    });
  }
}

// Um único valor (ex.: "qual o faturamento de hoje?") já está no resumo; tabela só quando ajuda
if (!(resumo && linhas.length === 1 && colunas.length <= 2)) {
  blocks.push({
    type: 'table',
    title: (ia && ia.titulo) || '',
    headers: colunas.map((c) => nomeColuna[c]),
    rows: linhas.map((l) => colunas.map((c) => fmt(l[c], formato[c]))),
  });
}

const insight = ia && ia.insight;
if (insight && insight.content) {
  const severidades = ['info', 'success', 'warning', 'danger'];
  blocks.push({
    type: 'insight',
    severity: severidades.includes(insight.severity) ? insight.severity : 'info',
    content: String(insight.content),
  });
}

return responder(blocks);
